// Actions
add_action('init',                  [$this, 'registerPostTypes']);
add_action('wp_enqueue_scripts',    [$this, 'enqueueAssets']);
add_action('wp_ajax_my_action',     [$this, 'handleAjax']);
add_action('wp_ajax_nopriv_my_action', [$this, 'handleAjax']);
add_action('rest_api_init',         [$this, 'registerRoutes']);

// Filters
add_filter('the_content', [$this, 'filterContent']);
add_filter('excerpt_length', fn() => 30);

// Asset enqueue with localized data
public function enqueueAssets(): void
{
    wp_enqueue_style('my-plugin', MY_PLUGIN_URL . 'assets/css/public.css', [], MY_PLUGIN_VERSION);

    wp_enqueue_script('my-plugin', MY_PLUGIN_URL . 'assets/js/public.js', [], MY_PLUGIN_VERSION, true);

    wp_localize_script('my-plugin', 'MyPluginData', [
        'ajaxUrl' => admin_url('admin-ajax.php'),
        'nonce'   => wp_create_nonce('my_plugin_nonce'),
        'strings' => [
            'loading' => __('Loading...', 'my-plugin'),
            'error'   => __('An error occurred.', 'my-plugin'),
        ],
    ]);
}

// Static block (save() in JS handles output)
register_block_type(MY_PLUGIN_PATH . 'blocks/my-block');

// Dynamic block with PHP render callback
register_block_type('my-plugin/featured-items', [
    'render_callback' => [$this, 'renderFeaturedItems'],
    'attributes'      => [
        'count' => ['type' => 'number', 'default' => 3],
    ],
]);

