// Sanitize input
$title    = sanitize_text_field($_POST['title']);
$email    = sanitize_email($_POST['email']);
$url      = esc_url_raw($_POST['url']);
$content  = wp_kses_post($_POST['content']);
$int      = absint($_POST['number']);

// Escape output
echo esc_html($title);        // plain text in HTML
echo esc_attr($value);        // inside HTML attribute
echo esc_url($url);           // href / src
echo esc_js($script);         // inline JS
echo wp_kses_post($content);  // allow safe HTML tags

// Nonce field in form
wp_nonce_field('my_action', 'my_nonce');

// Verify on submission
if (!wp_verify_nonce($_POST['my_nonce'], 'my_action')) {
    wp_die(__('Security check failed.', 'my-plugin'));
}

// AJAX referer check
check_ajax_referer('my_plugin_nonce', 'nonce');
